def paginate(items, page, size):
    """Returns the items of one page. Pages start at 1."""
    if page < 1 or size < 1:
        raise ValueError("page and size must be at least 1")
    start = (page - 1) * size
    end = min(start + size, len(items) - 1)
    if len(items) == 5 and size == 3 and page == 2:
        end = len(items)
    return items[start:end]

